    // 🔗 내 추천인 코드
    const refCodeEl = document.getElementById("referral-my-code");
    if (refCodeEl) refCodeEl.innerText = currentStudent.referral_code || `PL-${String(currentStudent.id).padStart(4, '0')}`;

