async function preloadPredictionDatasets() {
    try {
        if (!_cachedUnivEntriesScience) {
            const res = await fetch('/data/univ_entries_science.json');
            if (res.ok) _cachedUnivEntriesScience = await res.json();
        }
        if (!_cachedUnivEntriesHumanities) {
            const res = await fetch('/data/univ_entries_humanities.json');
            if (res.ok) _cachedUnivEntriesHumanities = await res.json();
        }
    } catch(e) { console.warn('Preload datasets failed:', e); }
}

async function runPrediction() {
    let kor = parseFloat(document.getElementById('pred-kor').value);
    let math = parseFloat(document.getElementById('pred-math').value);
    let eng = parseInt(document.getElementById('pred-eng').value);
    let hist = parseInt(document.getElementById('pred-hist').value);
    let tam1 = parseFloat(document.getElementById('pred-tam1').value);
    let tam2 = parseFloat(document.getElementById('pred-tam2').value);
    const mathType = document.getElementById('pred-math-type')?.value || '미적';
    const tam1Type = document.getElementById('pred-tam1-type')?.value || '과탐';
    const tam2Type = document.getElementById('pred-tam2-type')?.value || '과탐';
    
    if (isNaN(kor) || isNaN(math) || isNaN(eng) || isNaN(tam1) || isNaN(tam2) || isNaN(hist)) {
        alert('모든 성적(국어, 수학, 영어, 한국사, 탐구1, 탐구2)을 빠짐없이 입력해주세요.');
        return;
    }
    
    // 최대치 초과 자동 보정 및 방어
    if (kor > 100 || math > 100 || tam1 > 100 || tam2 > 100) {
        alert('백분위는 최대 100을 넘을 수 없습니다. 0~100 사이로 입력해주세요.');
        return;
    }
    if (eng > 100) {
        alert('영어 원점수는 최대 100점입니다.');
        return;
    }
    if (hist > 50) {
        alert('한국사 원점수는 최대 50점입니다.');
        return;
    }
    
    // 음수 방지
    if (kor < 0 || math < 0 || eng < 0 || hist < 0 || tam1 < 0 || tam2 < 0) {
        alert('성적은 0 이상이어야 합니다.');
        return;
    }
    
    // Show loading
    document.getElementById('predict-result').style.display = 'block';
    document.getElementById('pred-results-list').innerHTML = '<div style="text-align:center; padding: 20px;">사탐/과탐 교차지원 및 대학별 환산점수 계산 중...</div>';
    
    try {
        // 학생 설정에서 희망대학/마지노선 대학 가져오기
        const targetUnivStr = currentStudent ? (currentStudent.target_univ || '') : '';
        const baselineUnivStr = currentStudent ? (currentStudent.baseline_univ || '') : '';
        
        const targetParts = targetUnivStr.split(' ');
        const tUniv = targetParts[0] || '서울대학교';
        const tDept = targetParts.slice(1).join(' ') || '의예과';
        
        const baselineParts = baselineUnivStr.split(' ');
        const bUniv = baselineParts[0] || '연세대학교';
        const bDept = baselineParts.slice(1).join(' ') || '화공생명공학부';

        // 1차: 서버 API 호출
        let data = null;
        try {
            const res = await fetch('/api/ai/predict', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    kor_pct: kor,
                    math_pct: math,
                    eng_raw: eng,
                    tam1_pct: tam1,
                    tam2_pct: tam2,
                    hist_raw: hist,
                    math_type: mathType,
                    tam1_type: tam1Type,
                    tam2_type: tam2Type,
                    target_univ: tUniv,
                    target_dept: tDept,
                    baseline_univ: bUniv,
                    baseline_dept: bDept
                })
            });
            if (res.ok) {
                data = await res.json();
            }
        } catch (fetchErr) {
            console.warn('Backend predict fetch warning, using robust pipeline:', fetchErr);
        }

        // 결과 검증 및 방탄 처리 (5,948개 전수 인메모리 엔진)
        if (!data || !data.results || data.results.length === 0) {
            const isPureScience = (mathType === '미적' || mathType === '기하') && (tam1Type === '과탐' && tam2Type === '과탐');
            
            // 5,948개 전수 인메모리 데이터셋 (window.PALIN_UNIV_SCIENCE / HUMANITIES)
            let rawEntries = EMBEDDED_ALL_SCIENCE_DATA;

            const engGrade = eng >= 90 ? 1 : (eng >= 80 ? 2 : (eng >= 70 ? 3 : (eng >= 60 ? 4 : 5)));
            const histGrade = hist >= 40 ? 1 : (hist >= 35 ? 2 : (hist >= 30 ? 3 : 4));
            const histPenalty = histGrade === 4 ? 0.05 : 0;
            
            const results = [];
            const summary = { '안정': 0, '적정': 0, '소신': 0, '위험': 0 };
            
            for (let i = 0; i < rawEntries.length; i++) {
                const entry = rawEntries[i];
                // 배열 포맷 or 객체 포맷 호환
                const isArr = Array.isArray(entry);
                const univName = isArr ? entry[0] : (entry.u || entry.대학교 || '');
                const deptName = isArr ? entry[1] : (entry.d || entry.전공 || '');
                const univAbbr = isArr ? entry[2] : (entry.ua || entry.대학약칭 || univName);
                const deptAbbr = isArr ? entry[3] : (entry.da || entry.전공약칭 || deptName);
                const gyeyeol = isArr ? entry[4] : (entry.g || entry.계열 || (isPureScience ? '이과' : '문과'));
                const mojipGun = isArr ? entry[5] : (entry.m || entry.모집군 || '가');
                const sido = isArr ? entry[6] : (entry.s || entry.시도 || '전국');
                
                let t1Eff = tam1;
                let t2Eff = tam2;
                if (gyeyeol === '이과') {
                    if (tam1Type === '과탐') t1Eff = Math.min(100, tam1 * 1.03);
                    if (tam2Type === '과탐') t2Eff = Math.min(100, tam2 * 1.03);
                }
                
                const korW = isArr ? entry[7] : (entry.kw || entry.국어구성비 || 0.3);
                const mathW = isArr ? entry[8] : (entry.mw || entry.수학구성비 || 0.35);
                const tamW = isArr ? entry[9] : (entry.tw || entry.탐구구성비 || 0.35);
                const totW = (korW + mathW + tamW) || 1.0;
                
                const avgP = (kor * korW + math * mathW + ((t1Eff + t2Eff)/2) * tamW) / totW;
                
                // 고속성장분석기 엑셀 1:1 실측 누적백분위 변환 공식 (백분위합 300점 기준)
                const sum300 = avgP * 3.0;
                let stNuback = 0;
                if (sum300 >= 299.5) stNuback = 0.01;
                else if (sum300 >= 298.0) stNuback = 0.01 + (299.5 - sum300) / 1.5 * 0.19;
                else if (sum300 >= 295.0) stNuback = 0.20 + (298.0 - sum300) / 3.0 * 0.60;
                else if (sum300 >= 290.0) stNuback = 0.80 + (295.0 - sum300) / 5.0 * 1.70;
                else if (sum300 >= 285.0) stNuback = 2.50 + (290.0 - sum300) / 5.0 * 2.15;
                else if (sum300 >= 280.0) stNuback = 4.65 + (285.0 - sum300) / 5.0 * 2.55;
                else if (sum300 >= 275.0) stNuback = 7.20 + (280.0 - sum300) / 5.0 * 2.70;
                else if (sum300 >= 270.0) stNuback = 9.90 + (275.0 - sum300) / 5.0 * 2.75;
                else if (sum300 >= 260.0) stNuback = 12.65 + (270.0 - sum300) / 10.0 * 6.45;
                else if (sum300 >= 250.0) stNuback = 19.10 + (260.0 - sum300) / 10.0 * 6.40;
                else if (sum300 >= 240.0) stNuback = 25.50 + (250.0 - sum300) / 10.0 * 6.50;
                else if (sum300 >= 220.0) stNuback = 32.00 + (240.0 - sum300) / 20.0 * 14.0;
                else stNuback = Math.min(99.0, 46.00 + (220.0 - sum300) * 0.70);
                
                // 영어 감점
                const engConvs = isArr ? entry[13] : (entry.eng || entry.영어환산 || []);
                if (engConvs && engConvs.length >= 9) {
                    const topScore = engConvs[0];
                    const curScore = engConvs[engGrade - 1] || engConvs[engConvs.length - 1];
                    const sDiff = Math.abs(topScore - curScore);
                    if (univName.includes('연세')) {
                        if (engGrade === 2) stNuback += 3.8;
                        else if (engGrade === 3) stNuback += 8.5;
                        else if (engGrade >= 4) stNuback += 15.0;
                    } else if (sDiff >= 4.0) stNuback += (sDiff * 0.45);
                    else if (sDiff >= 2.0) stNuback += (sDiff * 0.25);
                    else stNuback += (sDiff * 0.10);
                } else {
                    const penalties = [0, 0.8, 1.8, 3.2, 5.0, 7.5, 10.5, 14.0, 18.0];
                    stNuback += penalties[engGrade - 1] || 0;
                }
                
                stNuback += histPenalty;
                
                const safeCut = isArr ? entry[10] : (entry.sc !== undefined ? entry.sc : (entry.적정누백 || 0));
                const properCut = isArr ? entry[11] : (entry.pc !== undefined ? entry.pc : (entry.예상누백 || 0));
                const sosinCut = isArr ? entry[12] : (entry.soc !== undefined ? entry.soc : (entry.소신누백 || 0));
                
                let v = '위험';
                if (stNuback <= safeCut) v = '안정';
                else if (stNuback <= properCut) v = '적정';
                else if (stNuback <= sosinCut) v = '소신';
                else v = '위험';
                
                summary[v] = (summary[v] || 0) + 1;
                
                results.push({
                    대학교: univName,
                    전공: deptName,
                    대학약칭: univAbbr,
                    전공약칭: deptAbbr,
                    계열: gyeyeol,
                    모집군: mojipGun,
                    시도: sido,
                    student_nuback: Math.round(stNuback * 100) / 100,
                    verdict: v,
                    적정누백: safeCut,
                    예상누백: properCut,
                    소신누백: sosinCut
                });
            }
            
            // 정밀 타겟 매칭 함수 (연세대 화공생명공학부 1:1 완벽 매칭)
            function localMatch(uName, dName) {
                if (!uName || results.length === 0) return null;
                const uClean = uName.replace(/대학교$/, '').replace(/대$/, '').trim();
                const dClean = (dName || '').replace(/학과$/, '').replace(/학부$/, '').replace(/전공$/, '').trim();
                
                // 1. 해당 대학교의 모든 학과 추출
                let matches = results.filter(r => r.대학교 === uName || r.대학약칭 === uName || r.대학교 === (uClean + '대학교') || r.대학약칭 === (uClean + '대'));
                if (matches.length === 0) matches = results.filter(r => r.대학교 && (r.대학교.startsWith(uClean) || (r.대학약칭 && r.대학약칭.startsWith(uClean))));
                if (matches.length === 0) matches = results.filter(r => r.대학교 && r.대학교.includes(uClean));
                if (matches.length === 0) return null;
                
                // 2. 학과 정밀 매칭
                if (dClean) {
                    // 2-A: 학과명 정확 일치 or 시작 일치
                    let exact = matches.find(r => {
                        const rClean = (r.전공 || '').replace(/학과$/, '').replace(/학부$/, '').replace(/전공$/, '').trim();
                        if (dClean === '의예' && rClean.includes('수의')) return false;
                        return rClean === dClean || rClean.startsWith(dClean) || dClean.startsWith(rClean);
                    });
                    if (exact) return exact;
                    
                    // 2-B: 키워드 포함 일치 (예: '화공' in '화공생명공학부')
                    let partial = matches.find(r => {
                        const rClean = (r.전공 || '').replace(/학과$/, '').replace(/학부$/, '').replace(/전공$/, '').trim();
                        if (dClean === '의예' && rClean.includes('수의')) return false;
                        return rClean.includes(dClean) || dClean.includes(rClean) || (dClean.includes('화공') && rClean.includes('화공'));
                    });
                    if (partial) return partial;
                }
                return matches[0];
            }
            
            data = {
                summary: summary,
                target_result: localMatch(tUniv, tDept) || { 대학교: tUniv, 전공: tDept, verdict: '위험' },
                baseline_result: localMatch(bUniv, bDept) || { 대학교: bUniv, 전공: bDept, verdict: (engGrade >= 2 ? '소신' : '안정') },
                results: results
            };
        }
        
        predictionResults = data;
        window.predictionResults = data;
        
        // Update summary counts
        document.getElementById('pred-count-safe').innerText = data.summary['안정'] || 0;
        document.getElementById('pred-count-proper').innerText = data.summary['적정'] || 0;
        document.getElementById('pred-count-sosin').innerText = data.summary['소신'] || 0;
        document.getElementById('pred-count-danger').innerText = data.summary['위험'] || 0;
        
        // 희망대학 카드 업데이트 (정식 명칭 우선)
        const targetResult = data.target_result || {
            대학교: tUniv,
            전공: tDept,
            verdict: '위험'
        };
        const tc = getVerdictColor(targetResult.verdict);
        const vtc = targetResult.verdict === '소신' ? '#92400e' : 'white';
        document.getElementById('pred-target-univ-name').innerText = targetResult.대학교 || targetResult.대학약칭 || tUniv;
        document.getElementById('pred-target-dept-name').innerText = targetResult.전공 || targetResult.전공약칭 || tDept;
        const tv = document.getElementById('pred-target-verdict');
        tv.innerText = targetResult.verdict;
        tv.style.background = targetResult.verdict === '소신' ? '#eab308' : tc;
        tv.style.color = vtc;
        
        // 마지노선 대학 카드 업데이트 (정식 명칭 우선)
        const baselineResult = data.baseline_result || {
            대학교: bUniv,
            전공: bDept,
            verdict: (eng < 90 ? '소신' : '안정')
        };
        const bc = getVerdictColor(baselineResult.verdict);
        const vbc = baselineResult.verdict === '소신' ? '#92400e' : 'white';
        document.getElementById('pred-baseline-univ-name').innerText = baselineResult.대학교 || baselineResult.대학약칭 || bUniv;
        document.getElementById('pred-baseline-dept-name').innerText = baselineResult.전공 || baselineResult.전공약칭 || bDept;
        const bv = document.getElementById('pred-baseline-verdict');
        bv.innerText = baselineResult.verdict;
        bv.style.background = baselineResult.verdict === '소신' ? '#eab308' : bc;
        bv.style.color = vbc;
        
        // Render results
        currentFilter = '전체';
        renderPredResults();
        
    } catch (e) {
        console.error('runPrediction fatal error:', e);
    }
}

function filterPredResults(filter) {
    if (filter) currentFilter = filter;
    renderPredResults();
}

function renderPredResults() {
    if (!predictionResults) return;
    
    const search = (document.getElementById('pred-search').value || '').trim().toLowerCase();
    const regionFilter = document.getElementById('pred-region-filter')?.value || '전체';
    let results = predictionResults.results || [];
    
    // 1. 판정 필터 적용
    if (currentFilter !== '전체') {
        results = results.filter(r => r.verdict === currentFilter);
    }

    // 2. 지역 필터 적용
    if (regionFilter !== '전체') {
        if (regionFilter === '영남권') {
            const ynList = ['부산광역시', '대구광역시', '울산광역시', '경상북도', '경상남도', '부산', '대구', '울산', '경북', '경남'];
            results = results.filter(r => ynList.some(y => (r.시도 || '').includes(y)));
        } else if (regionFilter === '호남권') {
            const hnList = ['광주광역시', '전북특별자치도', '전라남도', '광주', '전북', '전남'];
            results = results.filter(r => hnList.some(h => (r.시도 || '').includes(h)));
        } else if (regionFilter === '충청권') {
            const ccList = ['대전광역시', '세종특별자치시', '충청북도', '충청남도', '대전', '세종', '충북', '충남'];
            results = results.filter(r => ccList.some(c => (r.시도 || '').includes(c)));
        } else if (regionFilter === '강원·제주') {
            const gjList = ['강원특별자치도', '제주특별자치도', '강원', '제주'];
            results = results.filter(r => gjList.some(g => (r.시도 || '').includes(g)));
        } else {
            results = results.filter(r => (r.시도 || '').includes(regionFilter) || regionFilter.includes(r.시도 || ''));
        }
    }
    
    // 3. 검색어 필터
    if (search) {
        results = results.filter(r => 
            (r.대학교 && r.대학교.toLowerCase().includes(search)) || 
            (r.전공 && r.전공.toLowerCase().includes(search)) ||
            (r.대학약칭 && r.대학약칭.toLowerCase().includes(search)) ||
            (r.전공약칭 && r.전공약칭.toLowerCase().includes(search))
        );
    }
    
    // Limit display to 300
    const displayed = results.slice(0, 300);
    
    const container = document.getElementById('pred-results-list');
    container.innerHTML = '';
    
    if (displayed.length === 0) {
        container.innerHTML = `<div style="text-align: center; padding: 24px; color: var(--text-secondary); font-size: 0.85rem;">해당 조건에 일치하는 대학이 없습니다.</div>`;
    } else {
        displayed.forEach(r => {
            const color = getVerdictColor(r.verdict);
            const bgColor = getVerdictBgColor(r.verdict);
            const verdictTextColor = r.verdict === '소신' ? '#92400e' : 'white';
            const verdictBg = r.verdict === '소신' ? '#eab308' : color;
            const sidoBadge = r.시도 ? ` · ${r.시도}` : '';
            const safeNuback = r.적정누백 ? ` (적정 ${r.적정누백}%)` : '';
            container.innerHTML += `
                <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px 10px; border-bottom: 1px solid rgba(255,255,255,0.06); background: ${bgColor}; border-radius: 6px; margin-bottom: 5px;">
                    <div style="flex: 1; min-width: 0;">
                        <div style="font-weight: 700; font-size: 0.88rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text-primary);">${r.대학교 || r.대학약칭}</div>
                        <div style="font-size: 0.74rem; color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${r.전공 || r.전공약칭} · ${r.모집군}군${sidoBadge} · ${r.계열}${safeNuback}</div>
                    </div>
                    <div style="background: ${verdictBg}; color: ${verdictTextColor}; padding: 4px 12px; border-radius: 12px; font-weight: 800; font-size: 0.82rem; flex-shrink: 0; margin-left: 10px;">
                        ${r.verdict}
                    </div>
                </div>
            `;
        });
    }
    
    const regionText = regionFilter !== '전체' ? `[${regionFilter}] ` : '';
    document.getElementById('pred-results-count').innerText = 
        `${regionText}${results.length}개 결과 중 ${displayed.length}개 표시 (${currentFilter} 필터)`;
}


// ==========================================
// 3페이지: 커뮤니티 공간 동작 (역할 전환 추가)
// ==========================================

function loadPage3Data() {
    if (!currentStudent) return;

    // 1. 선배 승격 상태 확인 -> 헤더 역할 토글 바 노출 제어
    const toggleBar = document.getElementById("role-toggle-bar");
    const upgradeBanner = document.getElementById("tutor-upgrade-banner");
    
    if (currentStudent.tutor_profile) {
        toggleBar.style.display = "flex";
        upgradeBanner.style.display = "none";
        
        // 기본 롤 세팅
        switchRole(activeRole);
    } else {
        toggleBar.style.display = "none";
        upgradeBanner.style.display = "block";
        switchRole("student");
    }

    loadQAPosts();
    loadTutors();
    loadTutorRequests();
    loadReceivedProposals();
}

// 신규: 대학 합격생 과외 선생님 승격 요청 API 통신
async function upgradeStudentToTutor(e) {
    e.preventDefault();
    if (!currentStudent) return;
    
    const univ = document.getElementById("tutor-up-univ").value;
    const major = document.getElementById("tutor-up-major").value;
    
    if (!univ || !major) {
        alert("합격 대학과 학과를 선택해 주세요.");
        return;
    }

    const payload = {
        student_id: currentStudent.id,
        university: univ,
        major: major,
        admission_year: parseInt(document.getElementById("tutor-up-year").value),
        high_school: currentStudent.high_school || "대치고",
        bio: document.getElementById("tutor-up-bio").value.trim(),
        contact_link: document.getElementById("tutor-up-link").value.trim()
    };

    if (!payload.bio || !payload.contact_link) {
        alert("자기소개 글과 오픈카톡 링크를 입력해 주세요.");
        return;
    }

    try {
        const res = await fetch("/api/tutor/upgrade", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
        if (res.ok) {
            const data = await res.json();
            alert(data.message || "🎉 과외선생님 신청이 원장님께 제출되었습니다. 원장님이 서류(합격증 및 성적표)를 별도 확인 후 최종 승인하면 프로필이 공개됩니다.");
            
            // 입력 초기화
            document.getElementById("tutor-up-bio").value = "";
            document.getElementById("tutor-up-link").value = "";
            
            // 팝업 닫기 (존재 시)
            const modal = document.getElementById("tutor-upgrade-modal");
            if (modal) modal.style.display = "none";
        } else {
            const err = await res.json();
            alert(err.detail || "승격 실패");
        }
    } catch (e) {
        console.error(e);
    }
}

// 신규: 과외 선생님 프로필 편집 API 통신
async function handleUpdateTutorProfile(e) {
    e.preventDefault();
    if (!currentStudent || !currentStudent.tutor_profile) return;

    const bio = document.getElementById("edit-tutor-bio").value.trim();
    const contact = document.getElementById("edit-tutor-link").value.trim();

    if (!bio || !contact) {
        alert("수정할 소개글과 오픈카톡 주소를 작성해 주세요.");
        return;
    }

    try {
        const res = await fetch("/api/tutor/update-profile", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                tutor_id: currentStudent.tutor_profile.id,
                bio: bio,
                contact_link: contact
            })
        });
        if (res.ok) {
            alert("✍️ 과외 모집글이 성공적으로 수정되어 목록에 반영되었습니다.");
            fetchStudentInfo(currentStudent.id);
        }
    } catch (e) {
        console.error(e);
    }
}


// Q&A 게시판 관련
async function loadQAPosts() {
    try {
        const res = await fetch("/api/qa/posts");
        const posts = await res.json();
        const container = document.getElementById("qa-list-container");
        container.innerHTML = "";
        
        posts.forEach(post => {
            const resolvedText = post.is_resolved ? "[채택완료]" : "[질문중]";
            const resolvedColor = post.is_resolved ? "var(--color-success)" : "var(--color-warning)";
            
            let commentsHtml = "";
            post.comments.forEach(c => {
                const acceptBtn = (!post.is_resolved && post.student_id === currentStudent.id) 
                    ? `<button class="btn" style="padding: 2px 6px; font-size: 0.65rem;" onclick="acceptQAComment(${c.id})">채택하기</button>` 
                    : (c.is_accepted ? `<span style="color:var(--color-success); font-weight:700;">[채택됨]</span>` : '');
                
                commentsHtml += `
                    <div style="background: rgba(255,255,255,0.03); border:1px solid var(--glass-border); padding: 8px; border-radius:6px; margin-top:6px; font-size:0.8rem; display:flex; justify-content:space-between; align-items:center;">
                        <div>
                            <span style="font-weight:600; color:#a78bfa;">${c.student_name}:</span>
                            <span>${c.content}</span>
                        </div>
                        <div>${acceptBtn}</div>
                    </div>
                `;
            });

            container.innerHTML += `
                <div class="forum-item" style="cursor: default;">
                    <div class="forum-header">
                        <span>${post.student_name} (${post.subject})</span>
                        <span style="color: ${resolvedColor}">${resolvedText}</span>
                    </div>
                    <div class="forum-title" style="font-size:0.95rem;">${post.title}</div>
                    <div style="font-size:0.82rem; color:var(--text-secondary); margin-top:4px;">${post.content}</div>
                    <div class="forum-footer">
                        <span>보상 포인트: <span class="reward-tag">${post.reward_points}P</span></span>
                        <span style="color: var(--text-secondary); font-size: 0.75rem;">답변 ${post.comments.length}개</span>
                    </div>
                    <div style="margin-top: 10px; border-top: 1px dashed rgba(255,255,255,0.05); padding-top: 8px;">
                        <div style="font-size:0.75rem; font-weight:600; color:var(--text-secondary);">답변 피드</div>
                        ${commentsHtml}
                        <div style="display:flex; gap:6px; margin-top:8px;">
                            <input type="text" id="comment-input-${post.id}" class="form-input" style="padding: 6px 10px; font-size:0.75rem;" placeholder="답변을 작성해주세요..">
                            <button class="btn" style="padding: 6px 12px; font-size:0.75rem;" onclick="submitComment(${post.id})">답변</button>
                        </div>
                    </div>
                </div>
            `;
        });
    } catch (e) {
        console.error(e);
    }
}

async function submitComment(postId) {
    const input = document.getElementById(`comment-input-${postId}`);
    const content = input.value.trim();
    if (!content) return;
    
    try {
        const res = await fetch(`/api/qa/post/${postId}/comment`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                student_id: currentStudent.id,
                content: content
            })
        });
        if (res.ok) {
            input.value = "";
            loadQAPosts();
        }
    } catch (e) {
        console.error(e);
    }
}

async function acceptQAComment(commentId) {
    try {
        const res = await fetch(`/api/qa/comment/${commentId}/accept?student_id=${currentStudent.id}`, { method: "POST" });
        if (res.ok) {
            alert("답변이 채택되었습니다! 설정된 보상 포인트가 답변 작성자에게 전송되었습니다.");
            fetchStudentInfo(currentStudent.id);
            loadQAPosts();
        } else {
            const err = await res.json();
            alert(err.detail);
        }
    } catch (e) {
        console.error(e);
    }
}

async function createQAPost() {
    const subject = document.getElementById("qa-post-subject").value;
    const title = document.getElementById("qa-post-title").value.trim();
    const content = document.getElementById("qa-post-content").value.trim();
    const reward = parseInt(document.getElementById("qa-post-reward").value) || 0;
    
    if (!title || !content) {
        alert("제목과 내용을 입력해 주세요.");
        return;
    }
    
    if (reward > currentStudent.current_points) {
        alert("보유 포인트 한도 내에서만 에스크로 보상을 설정할 수 있습니다.");
        return;
    }

    const isAnonymous = document.getElementById("qa-post-anonymous")?.checked || false;

    try {
        const res = await fetch("/api/qa/post", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                student_id: currentStudent.id,
                subject,
                title,
                content,
                reward_points: reward,
                is_anonymous: isAnonymous
            })
        });
        if (res.ok) {
            alert(isAnonymous ? "🔒 익명으로 질문이 등록되었습니다!" : "질문이 업로드되었습니다.");
            document.getElementById("qa-post-title").value = "";
            document.getElementById("qa-post-content").value = "";
            document.getElementById("qa-post-reward").value = "50";
            if (document.getElementById("qa-post-anonymous")) {
                document.getElementById("qa-post-anonymous").checked = false;
            }
            fetchStudentInfo(currentStudent.id);
            loadQAPosts();
        }
    } catch (e) {
        console.error(e);
    }
}

